const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Point([56.28, 27.2]).buffer(50000); // A 50km buffer around a point in southern Iran
  const dateStr1 = '2020-01-08';
  const dateStr2 = '2020-01-13';

  // Sentinel-1 pre-processing function
  function s1_preprocess(image) {
    var desc = image.get('system:asset_id').getInfo();
    if (desc.includes('GRD')) {
      // Apply orbit file, thermal noise removal, calibration, speckle filter, and terrain correction
      // Simplified for conciseness; full process involves more steps for optimal results
      image = ee.Image(image)
        .select('VV'); // Select VV polarization
      // Apply a simple median filter for speckle reduction
      image = image.focal_median(50, 'circle', 'meters');
    }
    return image.copyProperties(image, ['system:time_start']);
  }

  // Function to calculate water area for a given date
  async function calculateWaterArea(date, geom) {
    let collection = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('resolution_meters', 10))
      .filterBounds(geom)
      .filterDate(date, ee.Date(date).advance(1, 'day')); // Filter for the exact day

    const colSize = collection.size().getInfo();
    if (colSize === 0) {
      return { area: null, imagesFound: 0 }; // Indicate no images
    }

    // Get the first image, assuming one image per day for the region is sufficient
    const image = collection.first();

    // Pre-process and apply water threshold
    const preprocessed = s1_preprocess(image);
    // Water threshold: areas with VV backscatter lower than -18 dB are typically water
    const waterMask = preprocessed.lt(-18);

    // Calculate water pixel count and area
    const scale = 100; // Use a coarser scale for faster computation
    const waterPixelCount = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    }).get('VV');

    const waterPixelCountInfo = waterPixelCount.getInfo();

    if (waterPixelCountInfo === null || isNaN(waterPixelCountInfo)) {
      return { area: null, imagesFound: colSize }; // Calculation failure
    }

    if (waterPixelCountInfo === 0) {
      return { area: 0, imagesFound: colSize }; // No valid water pixels detected
    }

    // Area of a single pixel at the given scale
    const pixelArea = ee.Number(scale).pow(2);
    const waterAreaSqM = ee.Number(waterPixelCountInfo).multiply(pixelArea).divide(1e6); // Convert to sq km

    return { area: waterAreaSqM.getInfo(), imagesFound: colSize };
  }

  // Calculate water area for both dates
  const result1 = await calculateWaterArea(dateStr1, region);
  const result2 = await calculateWaterArea(dateStr2, region);

  // Error handling C1: Empty Collection
  if (result1.imagesFound === 0 || result2.imagesFound === 0) {
    console.log(`Images for ${dateStr1}: ${result1.imagesFound}`);
    console.log(`Images for ${dateStr2}: ${result2.imagesFound}`);
    console.log("C1: Empty Collection (No images found for one or both dates).");
    return;
  }

  // Error handling C2: No Valid Pixels (after masking, 0 water pixels)
  // This case is explicitly handled as area: 0 and not null.
  // We'll check for nulls from C3.

  // Error handling C3: Calculation Failure
  if (result1.area === null || result2.area === null) {
    console.log(`Water area for ${dateStr1}: ${result1.area}`);
    console.log(`Water area for ${dateStr2}: ${result2.area}`);
    console.log("C3: Calculation Failure (Result is None, NaN, or invalid).");
    return;
  }

  const area1 = result1.area;
  const area2 = result2.area;

  console.log(`Water extent on ${dateStr1}: ${area1.toFixed(2)} km² (Images: ${result1.imagesFound})`);
  console.log(`Water extent on ${dateStr2}: ${area2.toFixed(2)} km² (Images: ${result2.imagesFound})`);

  // Comparison and Final Answer
  if (area2 > area1) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
